  preserveBlur = false,
  showOutline,
  pad = 32,
  optics,
  deformation,
  sceneRef,
  requireSceneCoverage = false,
  backdropRef,
  frameRate,
  tintBlendMode = "multiply",
  as = "div",
  asChild = false,
  readability,
  rendering = "auto",
  compositorReady = true,
  priority = 0,
  className = "",
  style,
  children,
  ref,
  ...rest
