    const element = rootEl.current,
      scene = source?.current;
    if (!requireSceneCoverage || !element || !scene) return;
    const measure = () => {
      const a = element.getBoundingClientRect(),
        b = scene.getBoundingClientRect();
      if (a.width > 0 && a.height > 0 && b.width > 0 && b.height > 0)
        setSourceCovered(
          a.left >= b.left - 0.5 &&
            a.top >= b.top - 0.5 &&
