            ? add([
                "padding-left",
                "padding-right",
                "border-left-width",
                "border-right-width",
              ])
            : 0);
      const h =
        box?.blockSize ??
        (parseFloat(css.height) || element.clientHeight) +
          (contentBox
            ? add([
                "padding-top",
                "padding-bottom",
                "border-top-width",
                "border-bottom-width",
              ])
            : 0);
