        <div
          aria-hidden="true"
          data-glass-clip=""
          style={{
            position: "absolute",
            inset: 0,
            zIndex: -1,
            pointerEvents: "none",
            clipPath: lensClipPath(size.w, size.h, safeRadius, shape),
            isolation: "isolate",
