          {/* Keep color finish outside the SVG; blur runs before its colored rim. */}
          {rendering !== "composited" && (
            <div
              data-glass-blur=""
              style={{
                position: "absolute",
                inset: -samplingPad,
                filter:
                  portable && !reduced
                    ? active
                      ? colorFinish
                      : diffuse
                    : undefined,
              }}
            >
              <div
                ref={layer}
                data-lens-layer=""
                className="glass-optical-layer"
                style={{
                  position: "absolute",
                  inset: 0,
