}
export function GlassPowerDialog({
  container,
  title = "Ready to shut down?",
  description = "Your open windows can be restored when you sign in again.",
  confirmLabel = "Shut down",
  trigger,
  onConfirm,
  ...props
}: GlassPowerDialogProps) {
  return (
    <Primitive.Root {...props}>
