}
export function GlassAddButton({ className }: { className?: string }) {
  const [added, setAdded] = useState(false);
  const [animate, setAnimate] = useState(false);
  return (
    <GlassButton
      shape="circle"
      aria-label={added ? "Remove from collection" : "Add to collection"}
      aria-pressed={added}
      className={className}
      onClick={(event) => {
        setAnimate(event.detail > 0);
        setAdded(!added);
      }}
    >
      <GlassStateSwap
        active={added}
        animate={animate}
        from={<GlassIcon name="plus" />}
        to={<GlassIcon name="check" />}
      />
    </GlassButton>
  );
}

