"use client";

import * as React from "react";
import { Switch as SwitchPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";
import { GlassLens } from "@/components/glass/glass-target-lens";
import {
  CONTROL_LENS_PRESETS,
  type ControlLensParameters,
} from "@/lib/glass-lens-optics";

export function GlassSwitch({
  className,
  size = "default",
  checked,
  defaultChecked = false,
  onCheckedChange,
  onKeyDown,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onLostPointerCapture,
  onBlur,
  onClick,
  lensParameters,
  opticalIdle,
  style,
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Root> & {
  size?: "sm" | "default";
  lensParameters?: Partial<ControlLensParameters>;
  opticalIdle?: boolean;
}) {
  const idle = opticalIdle ?? false;
  const [local, setLocal] = React.useState(defaultChecked);
  const enabled = checked ?? local;
  const [pointer, setPointer] = React.useState(false),
    [pressed, setPressed] = React.useState(false);
  const [dragPosition, setDragPosition] = React.useState<number | null>(null);
  const [pull, setPull] = React.useState(0);
  const gesture = React.useRef<{
    id: number;
    x: number;
    start: number;
    travel: number;
    position: number;
    moved: boolean;
  } | null>(null);
  const suppressClick = React.useRef(false);
  const timer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const stop = React.useCallback(() => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
    gesture.current = null;
    setDragPosition(null);
    setPull(0);
    setPressed(false);
  }, []);
  React.useEffect(() => {
    const hide = () => {
      if (document.hidden) stop();
    };
    window.addEventListener("blur", stop);
    document.addEventListener("visibilitychange", hide);
    return () => {
      if (timer.current) clearTimeout(timer.current);
      gesture.current = null;
      window.removeEventListener("blur", stop);
      document.removeEventListener("visibilitychange", hide);
    };
  }, [stop]);
  React.useEffect(() => {
    if (props.disabled) stop();
  }, [props.disabled, stop]);
  const release = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      timer.current = null;
      setPressed(false);
    }, 400);
  };
  const small = size === "sm",
    width = small ? 56 : 74,
    height = small ? 22 : 28;
  const thumbWidth = small ? 32 : 44,
    thumbHeight = small ? 18 : 22;
  const lensWidth = small ? 48 : 64,
    lensHeight = small ? 26 : 32;
  const inset = (lensWidth - thumbWidth) / 2 - 3,
    verticalInset = (lensHeight - height) / 2;
  const position = dragPosition ?? (enabled ? 1 : 0);
  const color = `color-mix(in srgb, var(--glass-switch-track, color-mix(in srgb, var(--foreground) 14%, var(--card))), var(--glass-action,#006de5) ${position * 100}%)`;
