    position: "absolute",
    borderRadius: 999,
    background: color,
    transition: pointer && dragPosition === null
      ? "background-color 180ms var(--ease-out)" : "none",
  };
  return (
    <SwitchPrimitive.Root
      {...props}
      checked={enabled}
      onCheckedChange={(next) => {
        if (checked === undefined) setLocal(next);
        onCheckedChange?.(next);
      }}
      onClick={(event) => {
        if (suppressClick.current && event.detail > 0) {
          suppressClick.current = false;
          event.preventDefault();
          return;
        }
        suppressClick.current = false;
        onClick?.(event);
      }}
      onKeyDown={(event) => {
        stop();
        suppressClick.current = false;
        setPointer(false);
        onKeyDown?.(event);
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.button !== 0 || event.defaultPrevented || props.disabled)
          return;
        if (gesture.current) return;
        stop();
        suppressClick.current = false;
        setPointer(true);
        setPressed(true);
        const bounds = event.currentTarget.getBoundingClientRect();
        gesture.current = {
          id: event.pointerId,
          x: event.clientX,
          start: enabled ? 1 : 0,
          position: enabled ? 1 : 0,
          travel: Math.max(1, (bounds.width / width) * (width - 6 - thumbWidth)),
          moved: false,
        };
        event.currentTarget.setPointerCapture?.(event.pointerId);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        const drag = gesture.current;
        if (
          !drag ||
          drag.id !== event.pointerId ||
          event.defaultPrevented ||
          props.disabled
