          return;
        const distance = event.clientX - drag.x;
        if (!drag.moved && Math.abs(distance) < 3) return;
        drag.moved = true;
        suppressClick.current = true;
        const raw = drag.start + distance / drag.travel;
        drag.position = Math.max(0, Math.min(1, raw));
