    const next = buildControlLensTextures(
      width, height, radius, optical,
    );
    if (root.current) {
      root.current.dataset.lensTextureMs = (
        performance.now() - started
      ).toFixed(2);
      root.current.dataset.lensMapRevisions = String(++revisions.current);
    }
